\documentclass{article}
\usepackage{amsmath}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows}
\usetikzlibrary{positioning}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}
\usepackage{tkz-euclide}
\usepackage{ifthen}
\usetkzobj{all}



\newcommand{\mycastdiagram}[3]{

	\def\Angle{#1}
	\def\Quadrant{#2}
	\def\Label{#3}

	\ifthenelse{\Quadrant=2}{\def\pos{0.4}}{}
	\ifthenelse{\Quadrant=3}{\def\pos{-0.4}}{}
	\ifthenelse{\Quadrant=4}{\def\pos{-0.4}}{}	

	%% Define some points that lie on the circle 
	\tkzDefPoints{0/0/O, 1.1/0/XX, -1.1/0/xx, 0/1.1/YY, 0/-1.1/yy}


	%% Define some points that lie on the grid extremes of the grid
	\tkzDefPoints{\xmin/0/X, \xmax/0/x, 0/\ymin/Y, 0/\ymax/y}

%	% Angles
	\tkzDefPointBy[rotation = center O angle \Angle](XX) \tkzGetPoint{A}
	\tkzDefPointBy[rotation = center O angle \Angle](xx) \tkzGetPoint{B}


	\tkzMarkAngle[draw=none, fill=\acolor, size=0.3](x,O,A); 
%	\tkzMarkAngle[draw=none, fill=\lcolor, size=0.3](A,O,X); 

	% Needed to sort out the angle position and the reference angle
	\ifthenelse{\Quadrant=1}{
		\def\pos{0.5}
		\tkzLabelAngle[pos=\pos ](x,O,A){\Label};
		\tkzLabelAngle[pos=0.85](x,O,A){$\theta_R$};
		\tkzMarkAngle[thick, arrows=-stealth, size=0.65](x,O,A); 


	}{}	

	% Needed to sort out the angle position and the reference angle
\ifthenelse{\Quadrant=2}{
	\def\pos{0.5}
	\tkzLabelAngle[pos=\pos](x,O,A){\Label};
	\tkzLabelAngle[pos=0.85](A,O,X){$\theta_R$};
	\tkzMarkAngle[thick, arrows=-stealth, size=0.65](A,O,X); 


}{}	


\ifthenelse{\Quadrant=3}{
	\def\pos{-0.5}
	\tkzLabelAngle[pos=\pos, xshift=-10pt](x,O,A){\Label};
	\tkzLabelAngle[pos=-0.85](X,O,A){$\theta_R$};
	\tkzMarkAngle[thick, arrows=-stealth, size=0.65](X,O,A); 


}{}	


\ifthenelse{\Quadrant=4}{
	\def\pos{-0.5}
	\tkzLabelAngle[pos=\pos](A,O,A){\Label};
	\tkzLabelAngle[pos=0.85](x,O,A){$\theta_R$};
	\tkzMarkAngle[thick, arrows=-stealth, size=0.65](A,O,x); 


}{}	




%	%Draw Segment
	\tkzDrawSegment[very thick, color=\pcolor](O,A)
	\tkzDrawSegment[very thick, color=\pcolor](O,XX)
%	\tkzDrawCircle[R, very thick,color=\lcolor](O, \r cm) 
	\tkzDrawVectors[style=thick](Y,y X,x)
	\tkzLabelPoints[below right](x)
	\tkzLabelPoints[above right](y)	
	\node[] at (1,1){$\textrm{A}$};
	\node[] at (-1,1){$\textrm{S}$};
	\node[] at (-1,-1){$\textrm{T}$};
	\node[] at (1,-1){$\textrm{C}$};






}




